/**
 * PipelineShield Live GitHub Actions Report Ingestion Route Handler.
 *
 * GET /api/latest-report
 *
 * Automatically discovers, downloads, extracts, validates, and serves the latest
 * authoritative security evaluation report generated by the CI Security Gate workflow.
 *
 * Security principles:
 * - Server-side only: GITHUB_TOKEN is never sent to the client.
 * - Pure in-memory ZIP processing: Zero filesystem writes.
 * - Bounds enforcement: Strict timeouts and size caps against memory exhaustion / zip bombs.
 * - Schema validation: Authoritative contract validation via validateReportSchema before returning.
 * - Fail-safe error propagation: Detailed sanitized errors without token leaks.
 */

import { NextRequest, NextResponse } from "next/server";
import { fetchLatestGitHubReport } from "@/lib/github-ingestion";

export async function GET(request: NextRequest) {
  const token = process.env.GITHUB_TOKEN;
  const repo = process.env.GITHUB_REPOSITORY;

  const url = new URL(request.url);
  const isRefresh = url.searchParams.get("refresh") === "true";

  const result = await fetchLatestGitHubReport({
    token,
    repo,
    isRefresh,
  });

  return NextResponse.json(result.body, {
    status: result.status,
    headers: result.headers,
  });
}
